import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import yaml from 'js-yaml';

const TEMPLATE = fileURLToPath(new URL('../../../policy/default-policy.yaml', import.meta.url));
const EMPTY_LINE_RE = /^(\s*allowed_servers:)[ \t]*\[[ \t]*\][ \t]*$/m;
const FLOW_LINE_RE = /^(\s*allowed_servers:)[ \t]*(\[.*\])[ \t]*$/m;

const HEADER = [
  '# Generated by `agentguard wrap`. Edit freely.',
  '# `agentguard wrap` only ever touches the mcp.allowed_servers line, and only',
  '# to ADD the names of servers you approved when you ran it.',
  '',
].join('\n');

/**
 * Makes sure the policy file the wrapped gateways point at exists. A wrapped
 * entry whose policy file is missing would fail to start, so this runs
 * BEFORE any client config is rewritten.
 *
 * First run: a copy of the shipped default policy with mcp.allowed_servers
 * set to the approved names. Later runs: leaves the file alone unless its
 * allowed_servers is a one-line list we can safely extend; otherwise returns
 * a notice telling the user what to add by hand.
 *
 * @returns {{created:boolean, updated:boolean, added:string[], notice:string|null}}
 */
export function ensurePolicy({ policyPath, names, backupDir, template = TEMPLATE }) {
  const wanted = [...new Set(names)];
  fs.mkdirSync(path.dirname(policyPath), { recursive: true });

  if (!fs.existsSync(policyPath)) {
    const text = fs.readFileSync(template, 'utf8');
    if (!EMPTY_LINE_RE.test(text)) throw new Error('default policy template has no "allowed_servers: []" line to fill in');
    fs.writeFileSync(policyPath, HEADER + text.replace(EMPTY_LINE_RE, `$1 ${JSON.stringify(wanted)}`));
    return { created: true, updated: false, added: wanted, notice: null };
  }

  const text = fs.readFileSync(policyPath, 'utf8');
  let current;
  try {
    current = yaml.load(text)?.mcp?.allowed_servers;
  } catch (err) {
    return { created: false, updated: false, added: [], notice: `${policyPath} is not valid YAML (${err.message}); left untouched` };
  }
  const have = Array.isArray(current) ? current : [];
  const missing = wanted.filter((n) => !have.includes(n));
  if (missing.length === 0) return { created: false, updated: false, added: [], notice: null };

  const m = text.match(FLOW_LINE_RE);
  let flow = null;
  try {
    flow = m ? yaml.load(m[2]) : null;
  } catch {
    flow = null;
  }
  if (!m || !Array.isArray(flow)) {
    return {
      created: false,
      updated: false,
      added: [],
      notice: `add these to mcp.allowed_servers in ${policyPath} by hand (it is not a one-line list): ${missing.join(', ')}`,
    };
  }

  fs.mkdirSync(backupDir, { recursive: true });
  fs.writeFileSync(path.join(backupDir, `${new Date().toISOString().replace(/[:.]/g, '-')}__policy.yaml.bak`), text);
  fs.writeFileSync(policyPath, text.replace(FLOW_LINE_RE, `$1 ${JSON.stringify([...flow, ...missing])}`));
  return { created: false, updated: true, added: missing, notice: null };
}
